from pathlib import Path
p=Path('/mnt/data/p22/app/models.py')
s=p.read_text()
s=s.replace('    amount=db.Column(db.Float, nullable=False, default=0)\n    invoice=db.relationship("FeeInvoice", back_populates="items")', '    amount=db.Column(db.Float, nullable=False, default=0)\n    fee_month=db.Column(db.Date, index=True)\n    invoice=db.relationship("FeeInvoice", back_populates="items")')
p.write_text(s)

p=Path('/mnt/data/p22/app/schema_upgrade.py')
s=p.read_text()
s=s.replace("    'transport_route': {'map_points': 'TEXT'},", "    'transport_route': {'map_points': 'TEXT'},\n    'fee_invoice_item': {'fee_month': 'DATE'},")
p.write_text(s)

p=Path('/mnt/data/p22/app/finance.py')
s=p.read_text()
s=s.replace('from datetime import datetime', 'from datetime import datetime, date\nimport calendar')
# insert helpers before generate route
marker='@finance_bp.route("/generate-voucher/<int:student_id>", methods=["GET", "POST"])'
helpers='''def _recommended_fee_month(today=None):\n    """School billing recommendation; can be overridden by the user on the calendar."""\n    today = today or date.today()\n    # Default: same month, with the school's configured advance summer billing pattern.\n    target_month = today.month\n    target_year = today.year\n    if today.month == 4:\n        target_month = 6\n    elif today.month == 5:\n        target_month = 7\n    return date(target_year, target_month, 1)\n\ndef _month_choices(year=None):\n    year = year or date.today().year\n    return [date(year, m, 1) for m in range(1, 13)]\n\ndef _parse_months(form):\n    values=[]\n    for raw in form.getlist('fee_months'):\n        try:\n            d=datetime.strptime(raw, '%Y-%m').date().replace(day=1)\n            values.append(d)\n        except ValueError:\n            continue\n    return sorted(set(values))\n\ndef _existing_month_invoices(student_id, fee_ids, months):\n    if not months: return []\n    invoices=[]\n    for inv in FeeInvoice.query.filter_by(student_id=student_id).order_by(FeeInvoice.id).all():\n        if inv.paid >= inv.amount: continue\n        for item in (inv.items or []):\n            if item.fee_structure_id in fee_ids and item.fee_month in months:\n                invoices.append(inv); break\n    return list({i.id:i for i in invoices}.values())\n\n'''
s=s.replace(marker, helpers+marker)
# replace generate route block up to bulk route
start=s.index('@finance_bp.route("/generate-voucher/<int:student_id>"')
end=s.index('@finance_bp.route("/bulk-vouchers"', start)
new='''@finance_bp.route("/generate-voucher/<int:student_id>", methods=["GET", "POST"])\n@login_required\n@roles_required("admin", "admission_officer")\ndef generate_voucher(student_id):\n    student = db.get_or_404(Student, student_id)\n    structures = FeeStructure.query.filter_by(is_active=True).order_by(FeeStructure.name).all()\n    today=date.today(); recommended=_recommended_fee_month(today)\n    months=_month_choices(today.year)\n    existing_due=[]\n    if request.method == "POST":\n        try:\n            selected_ids = list(dict.fromkeys(int(x) for x in request.form.getlist("fee_structure_ids") if x.isdigit()))\n            fee_months=_parse_months(request.form)\n            if not selected_ids or not fee_months: raise ValueError("selection")\n            structures_selected = FeeStructure.query.filter(FeeStructure.id.in_(selected_ids), FeeStructure.is_active.is_(True)).order_by(FeeStructure.name).all()\n            if len(structures_selected) != len(selected_ids): raise ValueError("fees")\n            existing_due=_existing_month_invoices(student.id, set(selected_ids), fee_months)\n            existing_ids={i.id for i in existing_due}\n            inv = FeeInvoice(invoice_no=next_code("invoice", "INV"), student_id=student.id, fee_type="Monthly / Multiple Fees", amount=0, paid=0, status="Unpaid", due_date=datetime.combine(fee_months[0], datetime.min.time()).date())\n            db.session.add(inv); db.session.flush()\n            total=0; new_items=0\n            for month in fee_months:\n                for fs in structures_selected:\n                    duplicate=False\n                    for old in existing_due:\n                        duplicate = any(x.fee_structure_id==fs.id and x.fee_month==month for x in (old.items or []))\n                        if duplicate: break\n                    if duplicate: continue\n                    amt=float(fs.amount or 0); total += amt; new_items += 1\n                    db.session.add(FeeInvoiceItem(invoice_id=inv.id, fee_structure_id=fs.id, description=f"{fs.name} - {month.strftime('%B %Y')}", amount=amt, fee_month=month))\n            if new_items == 0:\n                db.session.delete(inv); db.session.commit()\n                if existing_due:\n                    from .exports import build_bulk_voucher_pdf\n                    return build_bulk_voucher_pdf(existing_due)\n                raise ValueError("nothing")\n            inv.amount=round(total,2); inv.fee_type="Monthly / Multiple Fees"\n            audit("Generate Voucher", f"Voucher {inv.invoice_no} for {student.admission_no}; months={','.join(m.strftime('%Y-%m') for m in fee_months)}; items={new_items}")\n            db.session.commit()\n            all_invoices=existing_due+[inv]\n            from .exports import build_bulk_voucher_pdf\n            return build_bulk_voucher_pdf(all_invoices) if len(all_invoices)>1 else redirect(url_for("finance.voucher", invoice_id=inv.id))\n        except (ValueError, TypeError):\n            db.session.rollback(); flash("Please select at least one fee item and one billing month.", "danger")\n    return render_template("finance/generate_voucher.html", student=student, structures=structures, months=months, recommended=recommended, existing_due=existing_due)\n\n'''
s=s[:start]+new+s[end:]
# Replace bulk route block through voucher route
start=s.index('@finance_bp.route("/bulk-vouchers"')
end=s.index('@finance_bp.route("/voucher/<int:invoice_id>")', start)
new='''@finance_bp.route("/bulk-vouchers", methods=["GET", "POST"])\n@login_required\n@roles_required("admin", "accountant", "admission_officer")\ndef bulk_vouchers():\n    classes = ClassRoom.query.order_by(ClassRoom.name, ClassRoom.section).all()\n    structures = FeeStructure.query.filter_by(is_active=True).order_by(FeeStructure.name).all()\n    class_id = request.args.get("class_id", "").strip(); status = request.args.get("status", "Active").strip()\n    q=Student.query\n    if class_id.isdigit(): q=q.filter_by(class_id=int(class_id))\n    if status: q=q.filter_by(status=status)\n    students=q.order_by(Student.first_name, Student.last_name).all()\n    today=date.today(); recommended=_recommended_fee_month(today); months=_month_choices(today.year)\n    if request.method=="POST":\n        selected=[int(x) for x in request.form.getlist("student_ids") if x.isdigit()]\n        fs_ids=list(dict.fromkeys(int(x) for x in request.form.getlist("fee_structure_ids") if x.isdigit()))\n        fee_months=_parse_months(request.form)\n        if not selected or not fs_ids or not fee_months:\n            flash("Select students, fee items and at least one billing month.","danger")\n            return render_template("finance/bulk_vouchers.html",students=students,classes=classes,structures=structures,class_id=class_id,status=status,months=months,recommended=recommended)\n        try:\n            selected_structures=FeeStructure.query.filter(FeeStructure.id.in_(fs_ids),FeeStructure.is_active.is_(True)).order_by(FeeStructure.name).all()\n            if len(selected_structures)!=len(fs_ids): raise ValueError("inactive")\n            selected_students=Student.query.filter(Student.id.in_(selected)).order_by(Student.first_name,Student.last_name).all()\n            if not selected_students: raise ValueError("students")\n            invoices=[]\n            for student in selected_students:\n                existing=_existing_month_invoices(student.id,set(fs_ids),fee_months)\n                invoices.extend(existing)\n                inv=FeeInvoice(invoice_no=next_code("invoice","INV"),student_id=student.id,fee_type="Monthly / Multiple Fees",amount=0,paid=0,status="Unpaid",due_date=fee_months[0])\n                db.session.add(inv); db.session.flush(); total=0; new_items=0\n                for month in fee_months:\n                    for fs in selected_structures:\n                        if any(any(x.fee_structure_id==fs.id and x.fee_month==month for x in (old.items or [])) for old in existing): continue\n                        amt=float(fs.amount or 0); total+=amt; new_items+=1\n                        db.session.add(FeeInvoiceItem(invoice_id=inv.id,fee_structure_id=fs.id,description=f"{fs.name} - {month.strftime('%B %Y')}",amount=amt,fee_month=month))\n                if new_items: inv.amount=round(total,2); invoices.append(inv)\n                else: db.session.delete(inv)\n                audit("Bulk Generate Voucher",f"{student.admission_no}; months={','.join(m.strftime('%Y-%m') for m in fee_months)}; new_items={new_items}; existing_due={len(existing)}")\n            db.session.commit()\n            if not invoices: raise ValueError("nothing")\n            from .exports import build_bulk_voucher_pdf\n            return build_bulk_voucher_pdf(invoices)\n        except (ValueError,TypeError):\n            db.session.rollback(); flash("Invalid bulk voucher request.","danger")\n    return render_template("finance/bulk_vouchers.html",students=students,classes=classes,structures=structures,class_id=class_id,status=status,months=months,recommended=recommended)\n\n'''
s=s[:start]+new+s[end:]
p.write_text(s)
